      "text": "﴿رَبِّ ٱغۡفِرۡ لِي وَهَبۡ لِي مُلۡكࣰا لَّا يَنۢبَغِي لِأَحَدࣲ مِّنۢ بَعۡدِيٓۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ۝﴾",
